"use strict";

cc.Class({
  "extends": cc.Component,
  properties: {
    lab_content: cc.Label,
    btn_okay: cc.Button
  },
  onLoad: function onLoad() {
    this.btn_okay.node.on("click", CommonFun.getInstance().debounce(this.btnClick, 1), this);
    this.setLabContent();
  },
  btnClick: function btnClick(btn) {
    var btnName = btn.node.name;
    switch (btnName) {
      case this.btn_okay.node.name:
        GlobalCfg.G_COMPONENTS.Audio.playButton();
        this.node.destroy();
        break;
      default:
        break;
    }
    ;
  },
  setLabContent: function setLabContent() {
    var languagesType = I18NUtil.getInstance().getLanguageType();
    switch (languagesType) {
      case I18NLanguagesEnum.English:
        this.lab_content.string = "1. Order processing in 1-7 working days Please be patient.\n\n2. There may be a delay in disbursement to your bank account after the order state being successful. And delay days dependon the withdrawal way you choose.\n\n3. If you have problems with the order,Please contact our customer service.\n\n4. E-mail: " + GlobalCfg.USER_DATAS.customerService.email;
        break;
      case I18NLanguagesEnum.Hindi:
        this.lab_content.string = "1. \u0911\u0930\u094D\u0921\u0930 \u092A\u094D\u0930\u094B\u0938\u0947\u0938\u093F\u0902\u0917 1-7 \u0915\u093E\u0930\u094D\u092F \u0926\u093F\u0935\u0938\u094B\u0902 \u092E\u0947\u0902 \u0915\u0943\u092A\u092F\u093E \u0927\u0948\u0930\u094D\u092F \u0930\u0916\u0947\u0902\u0964\n\n2. \u0911\u0930\u094D\u0921\u0930 \u0938\u092B\u0932 \u0939\u094B\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u0906\u092A\u0915\u0947 \u092C\u0948\u0902\u0915 \u0916\u093E\u0924\u0947 \u092E\u0947\u0902 \u092D\u0941\u0917\u0924\u093E\u0928 \u092E\u0947\u0902 \u0926\u0947\u0930\u0940 \u0939\u094B \u0938\u0915\u0924\u0940 \u0939\u0948\u0964 \u0914\u0930 \u0926\u0947\u0930\u0940 \u0915\u0947 \u0926\u093F\u0928 \u0906\u092A\u0915\u0947 \u0926\u094D\u0935\u093E\u0930\u093E \u091A\u0941\u0928\u0947 \u0917\u090F \u0928\u093F\u0915\u093E\u0938\u0940 \u0915\u0947 \u0924\u0930\u0940\u0915\u0947 \u092A\u0930 \u0928\u093F\u0930\u094D\u092D\u0930 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964\n\n3. \u092F\u0926\u093F \u0906\u092A\u0915\u094B \u0911\u0930\u094D\u0921\u0930 \u092E\u0947\u0902 \u0915\u094B\u0908 \u0938\u092E\u0938\u094D\u092F\u093E \u0939\u0948, \u0924\u094B \u0915\u0943\u092A\u092F\u093E \u0939\u092E\u093E\u0930\u0940 \u0917\u094D\u0930\u093E\u0939\u0915 \u0938\u0947\u0935\u093E \u0938\u0947 \u0938\u0902\u092A\u0930\u094D\u0915 \u0915\u0930\u0947\u0902\u0964\n\n4. \u0908-\u092E\u0947\u0932: " + GlobalCfg.USER_DATAS.customerService.email;
        break;
      case I18NLanguagesEnum.Urdu:
        this.lab_content.string = "1. 1-7 \u06A9\u0627\u0645 \u06A9\u06D2 \u062F\u0646\u0648\u06BA \u0645\u06CC\u06BA \u0622\u0631\u0688\u0631 \u067E\u0631 \u06A9\u0627\u0631\u0631\u0648\u0627\u0626\u06CC \u06C1\u0648 \u0631\u06C1\u06CC \u06C1\u06D2\u060C \u0628\u0631\u0627\u06C1 \u06A9\u0631\u0645 \u0635\u0628\u0631 \u06A9\u0631\u06CC\u06BA\u06D4\n\n2. \u0622\u0631\u0688\u0631 \u06A9\u06CC \u062D\u0627\u0644\u062A \u06A9\u0627\u0645\u06CC\u0627\u0628 \u06C1\u0648\u0646\u06D2 \u06A9\u06D2 \u0628\u0639\u062F \u0622\u067E \u06A9\u06D2 \u0628\u06CC\u0646\u06A9 \u0627\u06A9\u0627\u0624\u0646\u0679 \u0645\u06CC\u06BA \u0631\u0642\u0645 \u06A9\u06CC \u0627\u062F\u0627\u0626\u06CC\u06AF\u06CC \u0645\u06CC\u06BA \u062A\u0627\u062E\u06CC\u0631 \u06C1\u0648 \u0633\u06A9\u062A\u06CC \u06C1\u06D2\u06D4 \u0627\u0648\u0631 \u062A\u0627\u062E\u06CC\u0631 \u06A9\u06D2 \u062F\u0646 \u0627\u0633 \u0628\u0627\u062A \u067E\u0631 \u0645\u0646\u062D\u0635\u0631 \u06C1\u06CC\u06BA \u06A9\u06C1 \u0622\u067E \u06A9\u0633 \u0637\u0631\u062D \u0648\u0627\u067E\u0633\u06CC \u06A9\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0631\u062A\u06D2 \u06C1\u06CC\u06BA\u06D4\n\n3\u06D4 \u0627\u06AF\u0631 \u0622\u067E \u06A9\u0648 \u0622\u0631\u0688\u0631 \u06A9\u06D2 \u0633\u0627\u062A\u06BE \u0645\u0633\u0627\u0626\u0644 \u06C1\u06CC\u06BA\u060C \u062A\u0648 \u0628\u0631\u0627\u06C1 \u06A9\u0631\u0645 \u06C1\u0645\u0627\u0631\u06CC \u06A9\u0633\u0679\u0645\u0631 \u0633\u0631\u0648\u0633 \u0633\u06D2 \u0631\u0627\u0628\u0637\u06C1 \u06A9\u0631\u06CC\u06BA\u06D4\n\n4: " + GlobalCfg.USER_DATAS.customerService.email;
        break;
      case I18NLanguagesEnum.Bengali:
        this.lab_content.string = "1. 1-7 \u0995\u09BE\u09B0\u09CD\u09AF\u09A6\u09BF\u09AC\u09B8\u09C7\u09B0 \u09AE\u09A7\u09CD\u09AF\u09C7 \u0985\u09B0\u09CD\u09A1\u09BE\u09B0 \u09AA\u09CD\u09B0\u0995\u09CD\u09B0\u09BF\u09AF\u09BC\u09BE \u0995\u09B0\u09BE \u09B9\u099A\u09CD\u099B\u09C7 \u0985\u09A8\u09C1\u0997\u09CD\u09B0\u09B9 \u0995\u09B0\u09C7 \u09A7\u09C8\u09B0\u09CD\u09AF \u09A7\u09B0\u09C1\u09A8\u0964\n\n2. \u0985\u09B0\u09CD\u09A1\u09BE\u09B0 \u09B8\u09CD\u099F\u09C7\u099F \u09B8\u09AB\u09B2 \u09B9\u0993\u09AF\u09BC\u09BE\u09B0 \u09AA\u09B0\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09AC\u09CD\u09AF\u09BE\u0999\u09CD\u0995 \u0985\u09CD\u09AF\u09BE\u0995\u09BE\u0989\u09A8\u09CD\u099F\u09C7 \u0985\u09B0\u09CD\u09A5 \u09AA\u09CD\u09B0\u09A6\u09BE\u09A8\u09C7 \u09AC\u09BF\u09B2\u09AE\u09CD\u09AC \u09B9\u09A4\u09C7 \u09AA\u09BE\u09B0\u09C7\u0964 \u098F\u09AC\u0982 \u09AC\u09BF\u09B2\u09AE\u09CD\u09AC\u09C7\u09B0 \u09A6\u09BF\u09A8\u0997\u09C1\u09B2\u09BF \u0986\u09AA\u09A8\u09BE\u09B0 \u09AC\u09C7\u099B\u09C7 \u09A8\u09C7\u0993\u09AF\u09BC\u09BE \u0989\u09AA\u09BE\u09AF\u09BC\u09C7\u09B0 \u0989\u09AA\u09B0 \u09A8\u09BF\u09B0\u09CD\u09AD\u09B0 \u0995\u09B0\u09C7\u0964\n\n3. \u0985\u09B0\u09CD\u09A1\u09BE\u09B0 \u09A8\u09BF\u09AF\u09BC\u09C7 \u0986\u09AA\u09A8\u09BE\u09B0 \u09B8\u09AE\u09B8\u09CD\u09AF\u09BE \u09B9\u09B2\u09C7, \u0985\u09A8\u09C1\u0997\u09CD\u09B0\u09B9 \u0995\u09B0\u09C7 \u0986\u09AE\u09BE\u09A6\u09C7\u09B0 \u0995\u09BE\u09B8\u09CD\u099F\u09AE\u09BE\u09B0 \u09B8\u09BE\u09B0\u09CD\u09AD\u09BF\u09B8\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AF\u09CB\u0997\u09BE\u09AF\u09CB\u0997 \u0995\u09B0\u09C1\u09A8\u0964\n\n4. \u0987-\u09AE\u09C7\u0987\u09B2: " + GlobalCfg.USER_DATAS.customerService.email;
        break;
      default:
        this.lab_content.string = "1. Order processing in 1-7 working days Please be patient.\n\n2. There may be a delay in disbursement to your bank account after the order state being successful. And delay days dependon the withdrawal way you choose.\n\n3. If you have problems with the order,Please contact our customer service.\n\n4. E-mail: " + GlobalCfg.USER_DATAS.customerService.email;
        break;
    }
    ;
  }
});

